  async calcFlow() {

    this.chartOptions.data = [];
    this.turboMap = +((this.form.value.boost + this.form.value.atm) / (this.form.value.atm - 1)).toFixed(1);
    const c = this.form.value.engineVolum * 0.061023744095;
    const map = (this.form.value.boost + this.form.value.atm);
    const temp = this.form.value.temp * 1.8 + 32;
    const x = (-0.0002 * this.form.value.temp) + 0.0801;
    this.dps = [];
    this.dps2 = [];
    this.dps3 = [];

    for (let i = 1; i < this.VE.length; i++) {

      const m = +(this.VE[i][0] * 0.145).toFixed(1);
      this.VE[i][0] = m;
      this.lbs[i][0] = m;
      this.cfm[i][0] = m;
      this.kg[i][0] = m;

      // tslint:disable-next-line: prefer-for-of
      for (let j = 1; j < this.VE[i].length; j++) {

        const ve = this.VE[i][j];
        const rpm = this.VE[0][j];

        const res = +((ve * 0.01 * rpm / 2 * c * (m + this.form.value.boost)) / (this.r * (460 + temp))).toFixed(1);

        this.VE[i][j] = res;
        this.lbs[i][j] = res;
        this.cfm[i][j] = +(res / x).toFixed(0);
        this.kg[i][j] = +(res / 132.3).toFixed(3);

        if (i == this.biggestMap) {

          if ((+this.form.value.peakTorquRpm > rpm)) {

            const percent = (rpm * 100 / (+this.form.value.peakTorquRpm));

            this.dps.push(new GraghModel(+((ve * 0.01 * rpm / 2 * c * (m + (this.form.value.boost * percent / 100))) / (this.r * (460 + temp))).toFixed(1), +(((+this.form.value.boost * percent / 100) + m) / (m - 1)).toFixed(1), rpm));
            this.dps2.push(new GraghModel(+(+((ve * 0.01 * rpm / 2 * c * (m + (this.form.value.boost * percent / 100))) / (this.r * (460 + temp))).toFixed(1) / x).toFixed(0), +(((+this.form.value.boost * percent / 100) + m) / (m - 1)).toFixed(1), rpm));
            this.dps3.push(new GraghModel(+(+((ve * 0.01 * rpm / 2 * c * (m + (this.form.value.boost * percent / 100))) / (this.r * (460 + temp))).toFixed(1) / 132.3).toFixed(3), +(((+this.form.value.boost * percent / 100) + m) / (m - 1)).toFixed(1), rpm));
          } else if (+this.form.value.peakTorquRpm <= rpm) {

            this.dps.push(new GraghModel(res, +((this.form.value.boost + m) / (m - 1)).toFixed(1), rpm));
            this.dps2.push(new GraghModel(+(res / x).toFixed(0), +((this.form.value.boost + m) / (m - 1)).toFixed(1), rpm));
            this.dps3.push(new GraghModel(+(res / 132.3).toFixed(3), +((this.form.value.boost + m) / (m - 1)).toFixed(1), rpm));
          }
        }
      }

      if (i == this.biggestMap) {

        this.chartOptions.data.push({
          type: 'splineArea',
          name: 'نمودار',
          toolTipContent: '<span style=\'"\'color: {color};\'"\'>{name}</span><br>دور موتور: {z}<br>نسبت فشار: {y}<br>جریان: {x}',
          dataPoints: [...this.dps],
          showInLegend: true
        });
      }
    }

    if (this.unit === 'lbs') {

      this.VE = [...this.lbs];

    } else if (this.unit === 'cfm') {

      this.VE = [...this.cfm];

    } else {

      this.VE = [...this.kg];
    }
  }

  async calcMinMax() {

    this.min = 300;
    this.max = 0;

    for (let i = 1; i < this.VE.length; i++) {

      // tslint:disable-next-line: prefer-for-of
      for (let j = 1; j < this.VE[i].length; j++) {

        const ve = this.VE[i][j];

        if (ve < this.min) {
          this.min = ve;
        }
        if (ve > this.max) {
          this.max = ve;
        }
      }
    }

    this.avg = (((this.max - this.min) / 2) + this.min);
  }

  calcColor(ve, j): string {

    let r = 135;
    let g = 135;
    let b = 135;

    if (j == 0) {
      return 'black';
    } else {

      if (ve >= this.avg) {

        r = ((((ve - this.min) * 100) / (this.max - this.min)) * 255) / 100;
        r += 3;
        g = ((100 - ((ve - this.avg) * 100) / (this.max - this.avg)) * 255) / 100;
        g += 34;

        if (g < 135) {
          g = 135;
        }
        if (g > 255) {
          g = 255;
        }
        if (r < 135) {
          r = 135;
        }
        if (r > 255) {
          r = 255;
        }
      } else {

        b = ((100 - (((ve - this.min) * 100) / (this.max - this.min))) * 255) / 100;
        b += 3;
        g = ((((ve - this.min) * 100) / (this.avg - this.min)) * 255) / 100;
        g += 34;

        if (g < 135) {
          g = 135;
        }
        if (g > 255) {
          g = 255;
        }
        if (b < 135) {
          b = 135;
        }
        if (b > 255) {
          b = 255;
        }
      }
      return 'rgb(' + r.toString() + ', ' + g.toString() + ', ' + b.toString() + ')';
    }
  }

